using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Globalization;using System.IO;using System.IO.Compression;using System.Linq;using System.Text.RegularExpressions;using System.Windows.Forms;
namespace BeamScheduleFormatter {
/* the earthquake map of the site (owner, 22 November 2026: "with map tapos may circles, diameter is based sa magnitude, kagaya sa
   model ni phivolcs"): coastline, active fault traces (the site's fault highlighted with its measured length), the search radius,
   the site, and every historical earthquake as a circle sized by magnitude and coloured by depth (shallow < 70 km red, 70-300 km
   orange, deeper blue); an optional PHIVOLCS active fault map overlay from a KMZ (its georeferenced image tiles). Wheel zooms, drag
   pans, double-click fits; the earthquake under the mouse is described in the corner. */
class EarthquakeMapView:Control {
 internal double Lat=double.NaN,Lon=double.NaN,RadiusKm=100;internal List<QuakeEvent> Quakes=new List<QuakeEvent>();internal FaultEstimate Fault;internal List<KeyValuePair<RectangleF,Image>> Overlay=new List<KeyValuePair<RectangleF,Image>>();
 /* fault lines traced from the KMZ map; a click picks a fault line (Ctrl+click adds one) */
 internal List<FaultTrace> Extra=new List<FaultTrace>();internal event Action<FaultTrace,bool> Picked;
 static readonly Color SiteFault=Color.FromArgb(25,70,210);
 float zoom=1;PointF pan;Point last,down;bool drag;QuakeEvent hover;
 public EarthquakeMapView(){DoubleBuffered=true;BackColor=Color.FromArgb(222,236,246);ResizeRedraw=true;Font=new Font("Segoe UI",8.5f);}
 /* screen point of lon, lat: the view spans the search radius (plus a margin) around the site */
 PointF P(double lon,double lat){double kx=Math.Cos(Lat*Math.PI/180);double span=Math.Max(RadiusKm,20)*2.3/111.0;float s=(float)(Math.Min(Width,Height)/span)*zoom;return new PointF(Width/2f+pan.X+(float)((lon-Lon)*kx*s),Height/2f+pan.Y-(float)((lat-Lat)*s));}
 protected override void OnMouseWheel(MouseEventArgs e){float k=e.Delta>0?1.2f:1/1.2f;var c=new PointF(Width/2f,Height/2f);pan=new PointF((pan.X-(e.X-c.X))*k+(e.X-c.X),(pan.Y-(e.Y-c.Y))*k+(e.Y-c.Y));zoom*=k;Invalidate();}
 protected override void OnMouseDown(MouseEventArgs e){Focus();drag=true;last=e.Location;down=e.Location;}
 protected override void OnMouseUp(MouseEventArgs e){drag=false;if(Math.Abs(e.X-down.X)+Math.Abs(e.Y-down.Y)>3||e.Button!=MouseButtons.Left||double.IsNaN(Lat)||Picked==null)return;var t=TraceAt(e.Location);if(t!=null)Picked(t,(ModifierKeys&Keys.Control)!=0);}
 /* the fault line within 6 pixels of a point: the traced map lines first, then the built-in traces */
 internal FaultTrace TraceAt(Point pt){FaultTrace best=null;double bd=6;foreach(var list in new[]{Extra,FaultTraces.All})foreach(var t in list){for(int k=1;k<t.Points.Count;k++){var a=P(t.Points[k-1][0],t.Points[k-1][1]);var b=P(t.Points[k][0],t.Points[k][1]);double dx=b.X-a.X,dy=b.Y-a.Y,L2=dx*dx+dy*dy;double u=L2<=0?0:Math.Max(0,Math.Min(1,((pt.X-a.X)*dx+(pt.Y-a.Y)*dy)/L2));double ex=a.X+u*dx-pt.X,ey=a.Y+u*dy-pt.Y,d=Math.Sqrt(ex*ex+ey*ey);if(d<bd){bd=d;best=t;}}if(best!=null&&list==Extra)return best;}return best;}
 protected override void OnDoubleClick(EventArgs e){zoom=1;pan=PointF.Empty;Invalidate();}
 protected override void OnMouseMove(MouseEventArgs e){if(drag){pan=new PointF(pan.X+e.X-last.X,pan.Y+e.Y-last.Y);last=e.Location;Invalidate();return;}if(double.IsNaN(Lat))return;QuakeEvent best=null;float bd=12;foreach(var q in Quakes){var p=P(q.Lon,q.Lat);float d=(float)Math.Sqrt((p.X-e.X)*(p.X-e.X)+(p.Y-e.Y)*(p.Y-e.Y));if(d<Math.Max(bd,Radius(q.Magnitude))){bd=d;best=q;}}if(best!=hover){hover=best;Invalidate();}}
 internal static float Radius(double m){return (float)Math.Max(2.5,Math.Pow(1.75,m-4)*3.2);}
 internal static Color DepthColor(double d){return double.IsNaN(d)||d<70?Color.FromArgb(215,48,39):d<300?Color.FromArgb(244,160,40):Color.FromArgb(49,112,190);}
 protected override void OnPaint(PaintEventArgs e){Paint(e.Graphics,true);}
 internal void Paint(Graphics g,bool interactive){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(BackColor);if(double.IsNaN(Lat)||double.IsNaN(Lon)){g.DrawString("Enter the site coordinates and look up the site to draw the earthquake map.",Font,Brushes.DimGray,12,12);return;}
  foreach(var o in Overlay){var a=P(o.Key.Left,o.Key.Bottom);var b=P(o.Key.Right,o.Key.Top);var rc=RectangleF.FromLTRB(a.X,a.Y,b.X,b.Y);if(rc.Right<0||rc.Bottom<0||rc.Left>Width||rc.Top>Height)continue;g.DrawImage(o.Value,rc);}
  using(var land=new Pen(Color.FromArgb(120,140,150),1.1f))using(var fill=new SolidBrush(Color.FromArgb(246,244,236)))foreach(var c in FaultTraces.Coast){var pts=c.Select(p=>P(p[0],p[1])).ToArray();if(pts.Length>2&&Math.Abs(c[0][0]-c[c.Count-1][0])+Math.Abs(c[0][1]-c[c.Count-1][1])<1e-6)g.FillPolygon(fill,pts);g.DrawLines(land,pts);}
  using(var pen=new Pen(Color.FromArgb(Overlay.Count>0?90:255,150,70,40),1.3f))foreach(var t in FaultTraces.All){if(Fault!=null&&Fault.Traces.Contains(t))continue;g.DrawLines(pen,t.Points.Select(p=>P(p[0],p[1])).ToArray());}
  /* the PHIVOLCS map lines (built in, or traced) when the map image itself is not shown */if(Overlay.Count==0)using(var pen=new Pen(Color.FromArgb(220,30,30),1.4f))foreach(var t in Extra){if(Fault!=null&&Fault.Traces.Contains(t))continue;g.DrawLines(pen,t.Points.Select(p=>P(p[0],p[1])).ToArray());}
  if(Fault!=null)using(var pen=new Pen(SiteFault,3f))foreach(var t in Fault.Traces)if(t.Points.Count>1)g.DrawLines(pen,t.Points.Select(p=>P(p[0],p[1])).ToArray());
  var site=P(Lon,Lat);double kx=Math.Cos(Lat*Math.PI/180);var edge=P(Lon+RadiusKm/(111.32*kx),Lat);float rr=edge.X-site.X;using(var pen=new Pen(Color.FromArgb(40,90,160),1.2f){DashStyle=DashStyle.Dash})g.DrawEllipse(pen,site.X-rr,site.Y-rr,2*rr,2*rr);
  foreach(var q in Quakes.OrderByDescending(q=>q.Magnitude)){var p=P(q.Lon,q.Lat);float r=Radius(q.Magnitude);var c=DepthColor(q.DepthKm);using(var b=new SolidBrush(Color.FromArgb(120,c)))g.FillEllipse(b,p.X-r,p.Y-r,2*r,2*r);using(var pen=new Pen(q==hover?Color.Black:c,q==hover?2f:1f))g.DrawEllipse(pen,p.X-r,p.Y-r,2*r,2*r);}
  if(Fault!=null&&!double.IsNaN(Fault.NearLat)&&Fault.Traces.Count>0){var np=P(Fault.NearLon,Fault.NearLat);using(var pen=new Pen(SiteFault,1.2f){DashStyle=DashStyle.Dot})g.DrawLine(pen,site,np);string lab=Fault.Name+"  L = "+Fault.LengthKm.ToString("0.0",CultureInfo.InvariantCulture)+" km, Mmax "+Fault.Mmax.ToString("0.00",CultureInfo.InvariantCulture);using(var f=new Font("Segoe UI",8.5f,FontStyle.Bold)){var sz=g.MeasureString(lab,f);using(var bg=new SolidBrush(Color.FromArgb(225,255,255,255)))g.FillRectangle(bg,np.X+5,np.Y-7,sz.Width,sz.Height);using(var br=new SolidBrush(SiteFault))g.DrawString(lab,f,br,np.X+5,np.Y-7);}}
  var star=Enumerable.Range(0,10).Select(k=>{double a=-Math.PI/2+k*Math.PI/5;float rad=k%2==0?9:4;return new PointF(site.X+(float)(rad*Math.Cos(a)),site.Y+(float)(rad*Math.Sin(a)));}).ToArray();g.FillPolygon(Brushes.Gold,star);g.DrawPolygon(Pens.Black,star);
  Legend(g);if(interactive){if(hover!=null){string t=hover.TimeUtc.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture)+"  M"+hover.Magnitude.ToString("0.0",CultureInfo.InvariantCulture)+(hover.MagType==""?"":" "+hover.MagType)+"  depth "+(double.IsNaN(hover.DepthKm)?"-":hover.DepthKm.ToString("0",CultureInfo.InvariantCulture)+" km")+"  "+hover.DistanceKm.ToString("0",CultureInfo.InvariantCulture)+" km away\r\n"+hover.Place;var sz=g.MeasureString(t,Font);g.FillRectangle(Brushes.White,8,8,sz.Width+8,sz.Height+6);g.DrawRectangle(Pens.Gray,8,8,sz.Width+8,sz.Height+6);g.DrawString(t,Font,Brushes.Black,12,11);}
   g.DrawString("Wheel: zoom   Drag: pan   Double-click: fit   Hover a circle for its details   Click a fault line to take it as the site's fault, Ctrl+click to add a part",Font,Brushes.DimGray,8,Height-18);}}
 void Legend(Graphics g){float x=Width-178,y=10,w=168,h=168;g.FillRectangle(new SolidBrush(Color.FromArgb(235,255,255,255)),x,y,w,h);g.DrawRectangle(Pens.Gray,x,y,w,h);using(var b=new Font("Segoe UI",8.5f,FontStyle.Bold))g.DrawString("MAGNITUDE",b,Brushes.Black,x+6,y+4);float cx=x+20,cy=y+50;foreach(var m in new[]{5.0,6.0,7.0}){float r=Radius(m);g.DrawEllipse(Pens.DimGray,cx-r,cy-r,2*r,2*r);g.DrawString("M"+m.ToString("0",CultureInfo.InvariantCulture),Font,Brushes.Black,cx-10,cy+r);cx+=r+28;}
  float ly=y+96;using(var b=new Font("Segoe UI",8.5f,FontStyle.Bold))g.DrawString("DEPTH",b,Brushes.Black,x+6,ly);ly+=16;foreach(var d in new[]{new{T="< 70 km",D=10.0},new{T="70 - 300 km",D=100.0},new{T="> 300 km",D=400.0}}){using(var br=new SolidBrush(DepthColor(d.D)))g.FillEllipse(br,x+8,ly+2,10,10);g.DrawString(d.T,Font,Brushes.Black,x+22,ly);ly+=15;}
  using(var p=new Pen(Color.FromArgb(150,70,40),1.6f))g.DrawLine(p,x+90,y+120,x+110,y+120);g.DrawString("fault",Font,Brushes.Black,x+114,y+113);using(var p=new Pen(SiteFault,3f))g.DrawLine(p,x+90,y+138,x+110,y+138);g.DrawString("site fault",Font,Brushes.Black,x+114,y+131);}
 /* a PHIVOLCS / Google Earth KMZ of ground overlays: the most detailed tiles (the deepest level of the region pyramid) */
 internal static List<KeyValuePair<RectangleF,Image>> ReadKmz(string path){var list=new List<KeyValuePair<RectangleF,Image>>();using(var zip=new ZipArchive(File.OpenRead(path),ZipArchiveMode.Read)){var kmlEntry=zip.Entries.FirstOrDefault(z=>z.FullName.EndsWith(".kml",StringComparison.OrdinalIgnoreCase));if(kmlEntry==null)throw new Exception("No KML in the KMZ.");string kml;using(var r=new StreamReader(kmlEntry.Open()))kml=r.ReadToEnd();
  var overlays=Regex.Matches(kml,@"<GroundOverlay>(.*?)</GroundOverlay>",RegexOptions.Singleline).Cast<Match>().Select(m=>m.Groups[1].Value).ToList();if(overlays.Count==0)throw new Exception("The KMZ has no ground overlay images (fault lines as vectors are not read).");
  Func<string,string,double> num=(s,tag)=>{var m=Regex.Match(s,"<"+tag+">\\s*([-0-9.eE]+)\\s*</"+tag+">");return m.Success?double.Parse(m.Groups[1].Value,CultureInfo.InvariantCulture):double.NaN;};
  var items=overlays.Select(o=>new{Href=Regex.Match(o,@"<href>\s*(.*?)\s*</href>",RegexOptions.Singleline).Groups[1].Value,N=num(o,"north"),S=num(o,"south"),E=num(o,"east"),W=num(o,"west")}).Where(o=>o.Href!=""&&!double.IsNaN(o.N)).ToList();
  /* the deepest level: the smallest tiles */double area=items.Min(o=>(o.N-o.S)*(o.E-o.W));foreach(var o in items.Where(o=>(o.N-o.S)*(o.E-o.W)<=area*4.01)){var entry=zip.Entries.FirstOrDefault(z=>z.FullName==o.Href||z.FullName.EndsWith("/"+o.Href));if(entry==null)continue;using(var s=entry.Open())using(var ms=new MemoryStream()){s.CopyTo(ms);ms.Position=0;list.Add(new KeyValuePair<RectangleF,Image>(RectangleF.FromLTRB((float)o.W,(float)o.N,(float)o.E,(float)o.S),Image.FromStream(new MemoryStream(ms.ToArray()))));}}}
  if(list.Count==0)throw new Exception("No overlay images could be read from the KMZ.");return list;}
}
}
